const input = $input.first().json.body;

if (!input || !input.patientTelegramChatId || !input.pickupCode) {
  return [{ json: { skipped: true, reason: 'Missing required fields' } }];
}

return [{ json: {
  chatId: input.patientTelegramChatId,
  prescriptionId: input.id,
  pickupCode: input.pickupCode
} }];
